7f0c3bb1b parser: fix insecure string pass (oss-fuzz 26325)
 src/flb_parser.c | 11 ++++++++++-
 1 file changed, 10 insertions(+), 1 deletion(-)
commit 7f0c3bb1bd8645ca556125b5afae8db77f973085
Author:     davkor <david@adalogics.com>
AuthorDate: Sat Oct 31 16:48:00 2020 +0000
Commit:     Eduardo Silva <edsiper@gmail.com>
CommitDate: Thu Nov 5 14:05:26 2020 -0600

    parser: fix insecure string pass (oss-fuzz 26325)

    Signed-off-by: davkor <david@adalogics.com>

diff --git a/src/flb_parser.c b/src/flb_parser.c
index d85cbcf5f..0a756f27c 100644
--- a/src/flb_parser.c
+++ b/src/flb_parser.c
@@ -871,7 +871,16 @@ int flb_parser_typecast(const char *key, int key_len,
                 error = FLB_TRUE;
             }
             if (error == FLB_TRUE) {
-                flb_warn("[PARSER] key=%s cast error. save as string.", key);
+                /* We need to null-terminate key for flb_warn, as it expects
+                 * a null-terminated string, which key is not guaranteed
+                 * to be */
+                char *nt_key = flb_malloc(key_len + 1);
+                if (nt_key != NULL) {
+                    memcpy(nt_key, key, key_len);
+                    nt_key[key_len] = '\0';
+                    flb_warn("[PARSER] key=%s cast error. save as string.", nt_key);
+                    flb_free(nt_key);
+                }
                 msgpack_pack_str(pck, val_len);
                 msgpack_pack_str_body(pck, val, val_len);
             }
commit f6a8de0a8ca7caf4d857d20e35420e4f0ade96f9
Author:     davkor <david@adalogics.com>
AuthorDate: Sat Oct 31 18:11:13 2020 +0000
Commit:     Eduardo Silva <edsiper@gmail.com>
CommitDate: Thu Nov 5 14:05:26 2020 -0600

    parser: ensure proper string null-termination (oss-fuzz 26327)

    Signed-off-by: davkor <david@adalogics.com>

diff --git a/src/flb_parser.c b/src/flb_parser.c
index 0a756f27c..f0089e4ab 100644
--- a/src/flb_parser.c
+++ b/src/flb_parser.c
@@ -765,6 +765,19 @@ int flb_parser_time_lookup(const char *time_str, size_t tsize,
         p = flb_strptime(time_ptr, parser->time_fmt_year, tm);
     }
     else {
+        /*
+         * We must ensure string passed to flb_strptime is
+         * null-terminated, which time_ptr is not guaranteed
+         * to be. So we use tmp to hold our string.
+         */
+        if (time_len >= sizeof(tmp)) {
+            return -1;
+        }
+        memcpy(tmp, time_ptr, time_len);
+        tmp[time_len] = '\0';
+        time_ptr = tmp;
+        time_len = strlen(tmp);
+
         p = flb_strptime(time_ptr, parser->time_fmt, tm);
     }
